package com.plantgrowth.forecasting.entity; import jakarta.persistence.*;import java.time.*; @Entity @Table(name="plants") public class Plant {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="owner_user_id") private User owner; @Column(name="plant_code") private String plantCode; @Column(name="plant_name") private String plantName; private String species; @Column(name="planting_date") private LocalDate plantingDate; @Column(name="image_url",length=500) private String imageUrl; @ManyToOne(optional=false,cascade=CascadeType.PERSIST) @JoinColumn(name="location_id") private GrowingLocation location; @Enumerated(EnumType.STRING) private Status status=Status.ACTIVE; public Long getId(){return id;}public User getOwner(){return owner;}public void setOwner(User x){owner=x;}public String getPlantCode(){return plantCode;}public void setPlantCode(String x){plantCode=x;}public String getPlantName(){return plantName;}public void setPlantName(String x){plantName=x;}public String getSpecies(){return species;}public void setSpecies(String x){species=x;}public LocalDate getPlantingDate(){return plantingDate;}public void setPlantingDate(LocalDate x){plantingDate=x;}public String getImageUrl(){return imageUrl;}public void setImageUrl(String x){imageUrl=x;}public GrowingLocation getLocation(){return location;}public void setLocation(GrowingLocation x){location=x;}public Status getStatus(){return status;}public void setStatus(Status x){status=x;}}
